(7647118, 1243333, 138630, '<td valign="top">Fresh, clean, and cheerful.  A favorite.</td>', 'Fresh, clean, and cheerful.  A favorite.', '2019-11-25 01:02:34.000000', NULL, 1),
(7647119, 1243335, 138630, '<td valign="top">Way to make use of a very funny capture.  This one makes me laugh.  I just wish the quality of the photo was better.</td>', 'Way to make use of a very funny capture.  This one makes me laugh.  I just wish the quality of the photo was better.', '2019-11-25 01:03:26.000000', NULL, 1),
(7647120, 1243288, 138630, '<td valign="top">Since the editing is extended, I''d have cleaned up the background.  Otherwise you made nice use of this.</td>', 'Since the editing is extended, I''d have cleaned up the background.  Otherwise you made nice use of this.', '2019-11-25 01:04:43.000000', NULL, 1),
(7647121, 1243324, 138630, '<td valign="top">Really nice angle that takes advantage of the blinds and makes them into an asset rather than a liability.  I''m not understanding why you didn''t write Season''s in smaller font?  I like the monochrome . . . but would have gone with something more cheerful than a brown or gray.</td>', 'Really nice angle that takes advantage of the blinds and makes them into an asset rather than a liability.  I''m not understanding why you didn''t write Season''s in smaller font?  I like the monochrome . . . but would have gone with something more cheerful than a brown or gray.', '2019-11-25 01:06:30.000000', NULL, 1),
(7647122, 1243319, 138630, '<td valign="top">Nice use of these decorations.  Sure wish you''d taken the time to clean up some of the distractions like the windows and car near the bottom and some of the signs.</td>', 'Nice use of these decorations.  Sure wish you''d taken the time to clean up some of the distractions like the windows and car near the bottom and some of the signs.', '2019-11-25 01:07:40.000000', NULL, 1),
(7647133, 1243319, 43774, '<td valign="top">Love the photo!! Not too keen on the text colour though.</td>', 'Love the photo!! Not too keen on the text colour though.', '2019-11-25 08:16:56.000000', NULL, 1),
(7647134, 1243293, 43774, '<td valign="top">Funny!</td>', 'Funny!', '2019-11-25 08:17:37.000000', NULL, 1),
